If $\phi$ is a $0$-phase, then
\begin{MathMaybe}
\mathbb{E}_{v} \left[ \tau(\phi) \right]
\leq
{\tau}^{*}(\phi) + 2 {\sigma}^{*}(\phi) + w(v) \, ;
\end{MathMaybe}
if $\phi$ is a $1$-phase, then
\begin{MathMaybe}
\mathbb{E}_{v} \left[ \tau(\phi) \right]
\leq
{\tau}^{*}(\phi) + 2 {\sigma}^{*}(\phi) \, .
\end{MathMaybe}
